    "pub_date": "2026-10-30 09:56:22",
    "author": "",
    "description": "在四川省成都市青城山麓，芒城村马家林盘里，烘烤斑竹的火盆烧得正旺，热浪扑面。青城马椅子市级代表性传承人马娇凑近火口，鼓起腮帮子使劲吹气，脸庞被火光映得通红。这叫“烤包口”，需要用正脸贴着炭火，火力全凭嘴吹，大脑缺氧是常事。一把马椅子不用一颗铁钉、一滴胶，全靠榫卯连接，常规使用寿命可达三十年以上。",
