    "content": "10月29日，航拍位于青海省茫崖市的中国石油青海油田海西200万千瓦风电项目建设现场。该项目地处柴达木盆地戈壁，是青海省陆上单体单期规模最大的风电项目，也是中国石油当前单体单期规模最大的风电项目。项目总装机容量200万千瓦，规划安装320台单机容量6.25兆瓦风电机组，目前已完成101台风机吊装作业，计划于2027年年底实现首台风机并网，2028年6月实现全容量投产，项目建成后，预计年均发电量可达51.04亿千瓦时。（无人机照片）中新社记者 马铭言 摄 10月29日，航拍位于青海省茫崖市的中国石油青海油田海西200…"
