    "description": "36氪获悉，国家统计局数据显示，前三季度，全国规模以上文化及相关产业企业实现营业收入108210亿元，同比增长4.3%。分领域看，文化核心领域实现营业收入75042亿元，同比增长5.1%。其中，文化投资运营、创意设计服务、新闻信息服务等3个行业大类营业收入实现较快增长，增速分别为11.7%、8.8%和7.3%。",
