    "content": "文 | 刘凌果 编辑 | 海若镜 10月14日，诺贝尔化学奖得主David Baker团队连发两篇《Nature》，宣布AI能从头设计蛋白酶；9月以来，Claude、Gemini 4接连宣称具备发现、设计新酶的能力。 AI4S水温沸腾，以酶为关键工具的昔日顶流“合成生物”，能否复制AI制药的升温路径，借由AI证明自己，重获资本青睐？ “直至今年，大多数企业都没从坑里爬出来。包括当年顶尖VC投的一批公司，甚至估值倒挂。”回顾上一周期，一位投资人感慨。 五年前，合成生物也曾风头无两。但此后，随着一批企业倒在中试和商业化…"
