    "content": "2026年10月30日 新华社北京10月29日电&nbsp;&nbsp;中宣部29日晚在京召开学习宣传贯彻党的二十届五中全会精神电视电话会议。中共中央政治局委员、中宣部部长李书磊出席会议并讲话。 会议指出，党的二十届五中全会是在基本实现社会主义现代化的关键时期召开的一次十分重要的会议。全会审议通过的《决定》，以习近平新时代中国特色社会主义思想为指导，深入贯彻习近平党建思想，系统总结新时代全面从严治党伟大成就，总结运用新时代全面从严治党宝贵经验，深入分析党的建设面临的新形势新任务新挑战，对持之以恒推进全面从严治党作出…"
