    "content": "2026年10月30日 本报北京10月29日电&nbsp;&nbsp;（记者王珂）记者从商务部获悉：前三季度，我国消费市场规模稳步扩大、居民消费结构持续优化，为经济增长发挥重要作用。 消费“主引擎”作用持续巩固，超大规模市场优势日益凸显。前三季度，最终消费支出对经济增长的贡献率为46.7%，高于上半年0.7个百分点，拉动国内生产总值增长2.1个百分点，持续保持经济增长第一拉动力。 “商品+服务”消费并重发展，保持良好增长势头；社会消费品零售总额有所回升，商品消费基本面良好；绿色、智能、健康消费需求旺盛，向新向好特征…"
