    "content": "2026年10月30日 第四届青奥会将于10月31日在塞内加尔首都达喀尔开幕，这是青奥圣火首次在非洲大陆点燃。恰逢“中非人文交流年”与达喀尔“青奥年”双年相逢，中非友好合作精神在热情好客的“特兰加”之国得到生动诠释。 真诚友好、平等尊重是两国关系的不变底色。中国与塞内加尔远隔重洋，但两国传统友谊经受住了风雨考验。习近平主席指出，中塞两国是发展振兴的同路人、好兄弟，强调双方要坚定支持彼此走独立自主的发展道路。塞方在涉及中方核心利益问题上给予中方坚定支持，积极响应习近平主席提出的四大全球倡议，率先加入世界人工智能合作组…"
