    "description": "2026年10月30日 人才，正在点亮一个个乡村。中央农业广播电视学校近期发布的《2026年全国高素质农民发展研究报告》显示，近年来，各地推动高素质农民培育计划落地实施，去年培育高素质农民61.36万人。同时，持续推进农村实用人才带头人培训、乡村产业振兴带头人培育“头雁”项目，开展学用贯通综合试点，多层次培养各类乡土人才。 “十五五”时期，坚持投资于物和投资于人紧密结合，各地加快适应乡村发展规律和产业变革特征，持续加力乡村人才队伍建设，…",
    "content": "2026年10月30日 制图：蔡华伟 \"> 人才，正在点亮一个个乡村。中央农业广播电视学校近期发布的《2026年全国高素质农民发展研究报告》显示，近年来，各地推动高素质农民培育计划落地实施，去年培育高素质农民61.36万人。同时，持续推进农村实用人才带头人培训、乡村产业振兴带头人培育“头雁”项目，开展学用贯通综合试点，多层次培养各类乡土人才。 “十五五”时期，坚持投资于物和投资于人紧密结合，各地加快适应乡村发展规律和产业变革特征，持续加力乡村人才队伍建设，引领乡村全面振兴的美好未来。 培训成效显著 发挥乡村发展带头…"
