    "author": "",
    "description": "2026年10月30日 又是一年秋光好，第三十三届中国杨凌农业高新科技成果博览会和2026上合组织农业博览会10月25日至29日举行。 本届杨凌农高会主题为“新质生产力·农业新未来”，同期举办的上合组织农博会以“深化务实合作·共绘发展蓝图”为主题。27个上合组织国家悉数参展，51个国家和地区、2200多家企业齐聚陕西省杨凌示范区，核心种源、数智农业、智能农机、设施农业、绿色种养等前沿科技集中亮相，共赴农业新质生产力的“科技之约”。 新技…",
    "content": "2026年10月30日 又是一年秋光好，第三十三届中国杨凌农业高新科技成果博览会和2026上合组织农业博览会10月25日至29日举行。 本届杨凌农高会主题为“新质生产力·农业新未来”，同期举办的上合组织农博会以“深化务实合作·共绘发展蓝图”为主题。27个上合组织国家悉数参展，51个国家和地区、2200多家企业齐聚陕西省杨凌示范区，核心种源、数智农业、智能农机、设施农业、绿色种养等前沿科技集中亮相，共赴农业新质生产力的“科技之约”。 新技术在突破 装备走出会场，科技助力增收 早上8点，杨凌农高会展馆入口处排起长队。展…"
