    "pub_date": "2026-10-30 08:26:02",
    "author": "",
    "description": "2026年10月30日 钱佳莹摄 \"> 普陀区新闻办供图 \"> 施旖雯摄 \"> 普陀区新闻办供图 \"> 10月31日，“科技创新·产业协同”2026沿沪宁城市协同创新日活动将在上海举行。活动期间，一批创新联合体、产业图谱、产融对接成果将陆续发布。 作为长三角创新密度最高、发展活力最强的经济走廊之一，沿沪宁产业创新带串联起上海和江苏南京、无锡、常州、苏州、南通、扬州、镇江、泰州9座城市，以不足全国0.6%的国土面积创造了近12%的国内生产…",
    "content": "2026年10月30日 来自沿沪宁城市的龙舟队队员在第二十二届上海苏州河城市龙舟邀请赛上奋力拼搏。 钱佳莹摄 \"> 位于上海普陀区的信泰中心。 普陀区新闻办供图 \"> 在TOP中央公园举办的春之交响草地音乐会上，市民踊跃参与互动。 施旖雯摄 \"> 位于上海普陀区真如城市副中心的海纳小镇数字创新中心。 普陀区新闻办供图 \"> 10月31日，“科技创新·产业协同”2026沿沪宁城市协同创新日活动将在上海举行。活动期间，一批创新联合体、产业图谱、产融对接成果将陆续发布。 作为长三角创新密度最高、发展活力最强的经济走廊之一…"
