    "description": "2026年10月30日 张奎楠摄，AI修饰生成素描画 \"> 东海边，又一世界级工程“上新”—— 日前，随着甬舟铁路桃夭门公铁两用大桥首节钢箱梁架设完成，甬舟铁路全线桥梁均进入架梁施工阶段。 甬舟铁路，西起浙江宁波东站，东至舟山本岛，正线全长76.4公里。线路虽然不长，却坐拥三座世界级桥梁，由西向东依次为西堠门、桃夭门、富翅门三座公铁两用大桥，是世界级跨海连岛工程。 其中，西堠门公铁两用大桥主跨1488米，为世界最大跨度公铁两用大桥；桃夭…",
