    "description": "2026年10月30日 资料图片 \"> 中国现代文学馆供图 \"> 长征，是一座文学的富矿。回望长征文学，“王愿坚”这个名字有着独特的意义。他的《三人行》《七根火柴》，是语文教材的常青树，镌刻进几代中国人的长征记忆。他参与编剧的《闪闪的红星》《四渡赤水》等电影，受到观众欢迎。他，是以非亲历者身份写长征的开启者。 叙述长征，最早是由长征亲历者开始的。从长征途中的毛泽东诗词、陈云的《随军西行见闻录》、邓发的《雪山草地行军记》，到红军将士集体创…",
    "content": "2026年10月30日 《百部红色经典·党费》（北京联合出版公司出版）、《七根火柴》（上海文艺出版社出版）。 资料图片 \"> 王愿坚短篇小说集《后代》，该书于一九五八年出版，收录《七根火柴》《三人行》等作品。 中国现代文学馆供图 \"> 长征，是一座文学的富矿。回望长征文学，“王愿坚”这个名字有着独特的意义。他的《三人行》《七根火柴》，是语文教材的常青树，镌刻进几代中国人的长征记忆。他参与编剧的《闪闪的红星》《四渡赤水》等电影，受到观众欢迎。他，是以非亲历者身份写长征的开启者。 叙述长征，最早是由长征亲历者开始的。从…"
