    "description": "2026年10月30日 绿 茶绘 \"> 10年前，从没想过我会和画画产生联系。那年孩子3岁，正是人们常说的“每个孩子都是天生艺术家”的时候，某天，正陪着他兴致勃勃地共读绘本，他突然说：“爸爸，你教我画画吧！”这一句，惊出我一身冷汗，从小到大，我从没有正式地画过画。 我们找出笔纸，照着绘本涂鸦起来。从此，共读绘本变成共画绘本，你一笔我一画，然后一起涂上花里胡哨的颜色，画画，真是乐趣无穷呀！慢慢地，我们也各自找到自己喜欢的题材，儿子爱画飞机…",
    "content": "2026年10月30日 湖南岳阳书门书屋手绘。 绿 茶绘 \"> 10年前，从没想过我会和画画产生联系。那年孩子3岁，正是人们常说的“每个孩子都是天生艺术家”的时候，某天，正陪着他兴致勃勃地共读绘本，他突然说：“爸爸，你教我画画吧！”这一句，惊出我一身冷汗，从小到大，我从没有正式地画过画。 我们找出笔纸，照着绘本涂鸦起来。从此，共读绘本变成共画绘本，你一笔我一画，然后一起涂上花里胡哨的颜色，画画，真是乐趣无穷呀！慢慢地，我们也各自找到自己喜欢的题材，儿子爱画飞机、火车、汽车，而我则画自家书房、朋友家书房，以及各种各样…"
