    "description": "2026年10月30日 国防工业出版社供图 \"> 我做过十几年科技报道，一直很喜欢看“大人物传记”。一个感受是，具备创造力的科技名人成长过程中，好奇心扮演着非常重要的角色。比尔·盖茨上小学的时候，父母给他买了一整套《世界图书百科全书》，使他对计算机产生兴趣，而马斯克在童年时就读了《大英百科全书》和大量科幻小说。于是我联想到，如何激发中国孩子的好奇心？ 现在的中国青少年，不只在科幻杂志或百科全书上读一读国外最新科技动态，他们还坐高铁列车出…",
    "content": "2026年10月30日 球罐型液化天然气船图解。 国防工业出版社供图 \"> 我做过十几年科技报道，一直很喜欢看“大人物传记”。一个感受是，具备创造力的科技名人成长过程中，好奇心扮演着非常重要的角色。比尔·盖茨上小学的时候，父母给他买了一整套《世界图书百科全书》，使他对计算机产生兴趣，而马斯克在童年时就读了《大英百科全书》和大量科幻小说。于是我联想到，如何激发中国孩子的好奇心？ 现在的中国青少年，不只在科幻杂志或百科全书上读一读国外最新科技动态，他们还坐高铁列车出行，看火箭发射直播，看得见、摸得着的高科技产品遍布身边…"
