    "content": "2026年10月30日 《至人庄子》：周国平著；人民文学出版社出版。 \"> 在忙碌紧张的现代社会中，很多人都在寻觅安顿心灵的方法。哲学家周国平在新作《至人庄子》中，给出了一种思路：2000多年前，庄子过上了一种既不内卷也不躺平的自由快乐的生活，这就是“逍遥”。 “至人”是庄子定义与向往的最高境界的人，而周国平就把庄子称为“至人”——本真又通透。《至人庄子》基于作者80多年人生阅历，把对庄子的深刻体悟，用流畅的散文娓娓道来，呈现出跨越2000多年的思想共振。 本书重点阐述了庄子的人生论和认识论。庄子的人生论为“逍遥”…"
