    "title": "西藏南部将有强雨雪天气 北方将有大风降温过程",
    "link": "https://www.chinanews.com.cn/sh/2026/10-30/10723103.shtml",
    "pub_date": "2026-10-30 08:17:24",
    "author": "",
    "description": "中新网10月30日电 据中央气象台网站消息，昨日，海南中东部、广东西南部局地出现大暴雨，西藏、内蒙古、黑龙江出现较强降雪。预计今明两天，青藏高原中东部有明显雨雪天气，其中西藏南部有强雨雪，注意防范次生灾害；东北、华北北部、内蒙古等地有大风降温，内蒙古、黑龙江局地有较强降雪，渤海、黄海等海域风力大，注意防范对海陆交通、能源供应、农牧业等的影响。",
